INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('curse', '저주', '[{"pos": "n.", "ko": "저주, 불운을 비는 말"}, {"pos": "v.", "ko": "저주하다, 욕설하다"}]'::jsonb, 'Some people believe that the old house is under a curse.', '일부 사람들은 그 오래된 집에 저주가 걸렸다고 믿는다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('curve', '곡선', '[{"pos": "n.", "ko": "곡선, 굽은 부분"}, {"pos": "v.", "ko": "구부러지다, 곡선을 이루다"}]'::jsonb, 'The road has a sharp curve just before the bridge.', '그 도로는 다리 바로 앞에 급한 곡선이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('cynical', '냉소적인', '[{"pos": "a.", "ko": "냉소적인, 비꼬는"}, {"pos": "a.", "ko": "의심 많은, 인간을 불신하는"}]'::jsonb, 'Some people become cynical after experiencing repeated disappointments.', '반복된 실망을 겪으면 냉소적으로 변하는 사람도 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('damp', '축축한', '[{"pos": "a.", "ko": "축축한, 습기 찬"}, {"pos": "n.", "ko": "습기, 축축함"}]'::jsonb, 'The clothes felt damp after being left outside overnight.', '옷을 밤새 밖에 두었더니 축축해졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dare', '감히 ~하다', '[{"pos": "v.", "ko": "감히 ~하다, ~할 용기가 있다"}, {"pos": "n.", "ko": "도전, 용기"}]'::jsonb, 'Few students dare to speak up in front of the whole class.', '전체 반 앞에서 감히 말하는 학생은 거의 없다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dawn', '새벽', '[{"pos": "n.", "ko": "새벽, 동틀 녘"}, {"pos": "v.", "ko": "밝아지다, 시작되다"}, {"pos": "v.", "ko": "이해되기 시작하다"}]'::jsonb, 'They started their journey at dawn to avoid the heat.', '그들은 더위를 피하려고 새벽에 여행을 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deal', '거래', '[{"pos": "n.", "ko": "거래, 합의"}, {"pos": "v.", "ko": "다루다, 처리하다"}]'::jsonb, 'The two companies finally reached a deal after long negotiations.', '두 회사는 오랜 협상 끝에 마침내 거래에 합의했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('debate', '토론', '[{"pos": "n.", "ko": "토론, 논쟁"}, {"pos": "v.", "ko": "토론하다, 논쟁하다"}, {"pos": "v.", "ko": "숙고하다, 신중히 검토하다"}]'::jsonb, 'There was a heated debate about the new education policy.', '새 교육 정책에 대해 열띤 토론이 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('debt', '빚', '[{"pos": "n.", "ko": "빚, 부채"}, {"pos": "n.", "ko": "신세, 은혜"}]'::jsonb, 'He worked hard to pay off his debt after college.', '그는 대학 졸업 후 빚을 갚기 위해 열심히 일했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decade', '10년', '[{"pos": "n.", "ko": "10년, 10년간"}]'::jsonb, 'A lot can change in a single decade.', '10년 만에도 많은 것이 변할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decay', '썩다', '[{"pos": "v.", "ko": "썩다, 부패하다"}, {"pos": "v.", "ko": "쇠퇴하다, 약해지다"}, {"pos": "n.", "ko": "부패, 썩음"}, {"pos": "n.", "ko": "쇠퇴, 약화"}]'::jsonb, 'If you leave food out too long, it will start to decay.', '음식을 오래 두면 썩기 시작한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deceive', '속이다', '[{"pos": "v.", "ko": "속이다, 기만하다"}]'::jsonb, 'She tried to deceive her parents about her test results.', '그녀는 시험 결과를 부모님께 속이려 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decent', '괜찮은', '[{"pos": "a.", "ko": "괜찮은, 품위 있는"}, {"pos": "a.", "ko": "예의 바른, 단정한"}]'::jsonb, 'He found a decent job after graduating from university.', '그는 대학 졸업 후 괜찮은 직장을 구했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decide', '결정하다', '[{"pos": "v.", "ko": "결정하다, 결심하다"}]'::jsonb, 'She will decide whether to join the club by tomorrow.', '그녀는 내일까지 동아리에 가입할지 결정할 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deck', '갑판', '[{"pos": "n.", "ko": "갑판, (배의) 바깥 바닥"}, {"pos": "n.", "ko": "(카드) 한 벌"}]'::jsonb, 'Passengers gathered on the deck to enjoy the sunset.', '승객들은 갑판에 모여 석양을 감상했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('declare', '선언하다', '[{"pos": "v.", "ko": "공식적으로 밝히다, 선언하다"}, {"pos": "v.", "ko": "(세관 등에) 신고하다"}]'::jsonb, 'The president will declare his decision to the public tomorrow.', '대통령은 내일 대중에게 자신의 결정을 발표할 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decline', '감소하다', '[{"pos": "v.", "ko": "수량이나 질이 줄어들다, 감소하다"}, {"pos": "v.", "ko": "(정중히) 거절하다"}, {"pos": "n.", "ko": "감소, 하락"}]'::jsonb, 'The population of the city continues to decline every year.', '그 도시의 인구는 해마다 계속 줄어들고 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decode', '해독하다', '[{"pos": "v.", "ko": "암호를 해독하다"}, {"pos": "v.", "ko": "의미를 이해하다"}]'::jsonb, 'Scientists worked together to decode the mysterious ancient script.', '과학자들은 신비로운 고대 문자를 해독하기 위해 협력했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decorate', '장식하다', '[{"pos": "v.", "ko": "장식하다, 꾸미다"}, {"pos": "v.", "ko": "훈장을 수여하다"}]'::jsonb, 'They decorated the classroom with balloons for the festival.', '그들은 축제를 위해 교실을 풍선으로 꾸몄다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decrease', '감소하다', '[{"pos": "v.", "ko": "수나 양이 줄다, 감소하다"}, {"pos": "v.", "ko": "줄이다, 감소시키다"}, {"pos": "n.", "ko": "감소, 축소"}]'::jsonb, 'The company’s profits began to decrease after the new law was passed.', '새 법이 통과된 후 그 회사의 이익이 줄기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dedicate', '헌신하다', '[{"pos": "v.", "ko": "시간이나 노력을 바치다, 헌신하다"}, {"pos": "v.", "ko": "(건물·책 등을) 헌정하다"}]'::jsonb, 'She decided to dedicate her life to helping the poor.', '그녀는 가난한 사람들을 돕는 데 평생을 바치기로 결심했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deed', '행위', '[{"pos": "n.", "ko": "행위, 행동"}, {"pos": "n.", "ko": "(특히 법적) 증서, 문서"}]'::jsonb, 'A single good deed can make a big difference in someone''s life.', '작은 선행 하나가 누군가의 삶에 큰 변화를 줄 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('defeat', '이기다', '[{"pos": "v.", "ko": "상대방을 이기다, 패배시키다"}, {"pos": "n.", "ko": "패배"}]'::jsonb, 'The team managed to defeat their strongest rivals in the final match.', '그 팀은 결승전에서 가장 강한 라이벌을 이기는 데 성공했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('defect', '결함', '[{"pos": "n.", "ko": "결점, 결함, 흠"}]'::jsonb, 'The product was recalled due to a serious safety defect.', '그 제품은 심각한 안전 결함 때문에 리콜되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('defend', '방어하다', '[{"pos": "v.", "ko": "공격이나 위험으로부터 지키다, 방어하다"}, {"pos": "v.", "ko": "옹호하다, 변호하다"}]'::jsonb, 'The soldiers were trained to defend the country from any threat.', '군인들은 어떤 위협으로부터도 나라를 방어하도록 훈련받았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deficient', '부족한', '[{"pos": "a.", "ko": "필요한 것이 부족한"}, {"pos": "a.", "ko": "결함이 있는"}]'::jsonb, 'A diet deficient in vitamins can cause serious health problems.', '비타민이 부족한 식단은 심각한 건강 문제를 일으킬 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('define', '정의하다', '[{"pos": "v.", "ko": "정의하다, 의미를 분명히 밝히다"}, {"pos": "v.", "ko": "경계나 범위를 규정하다"}]'::jsonb, 'It is important to define your goals before starting a new project.', '새로운 프로젝트를 시작하기 전에 목표를 정의하는 것이 중요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deflect', '방향을 바꾸다', '[{"pos": "v.", "ko": "방향을 바꾸다, 빗나가게 하다"}, {"pos": "v.", "ko": "(비판, 관심 등을) 피하다"}]'::jsonb, 'The shield was designed to deflect enemy attacks during battle.', '그 방패는 전투 중 적의 공격을 방향을 바꾸도록 설계되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('defy', '반항하다', '[{"pos": "v.", "ko": "(권위, 규칙 등에) 반항하다, 도전하다"}, {"pos": "v.", "ko": "무시하다"}]'::jsonb, 'The young artist defied the traditional rules of painting.', '그 젊은 예술가는 전통적인 그림 규칙에 반항했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('degenerate', '악화되다', '[{"pos": "v.", "ko": "악화되다, 퇴보하다"}, {"pos": "a.", "ko": "타락한, 퇴폐적인"}]'::jsonb, 'The quality of the service began to degenerate over time.', '서비스의 질이 시간이 지나면서 악화되기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('degrade', '품위를 떨어뜨리다', '[{"pos": "v.", "ko": "품위를 떨어뜨리다, 비하하다"}, {"pos": "v.", "ko": "(화학적으로) 분해하다"}]'::jsonb, 'No one should degrade others because of their background.', '누구도 다른 사람의 배경 때문에 그들을 비하해서는 안 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dehydrate', '탈수하다', '[{"pos": "v.", "ko": "수분을 제거하다, 탈수하다"}, {"pos": "v.", "ko": "건조시키다"}]'::jsonb, 'Athletes can dehydrate quickly if they do not drink enough water.', '운동선수들은 충분히 물을 마시지 않으면 금방 탈수될 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('delay', '연기하다', '[{"pos": "v.", "ko": "연기하다, 늦추다"}, {"pos": "n.", "ko": "지연, 연기"}]'::jsonb, 'The heavy rain may delay the start of the soccer match.', '폭우로 축구 경기가 시작이 연기될 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('delegate', '대표자', '[{"pos": "n.", "ko": "대표자, 대리인"}, {"pos": "v.", "ko": "(권한, 임무 등을) 위임하다"}, {"pos": "v.", "ko": "대표로 임명하다"}]'::jsonb, 'Each country sent a delegate to the international conference.', '각 나라는 국제 회의에 대표자를 보냈다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deliberate', '의도적인', '[{"pos": "a.", "ko": "의도적인, 고의의"}, {"pos": "a.", "ko": "신중한, 숙고하는"}, {"pos": "v.", "ko": "숙고하다, 심사숙고하다"}]'::jsonb, 'His actions were deliberate and meant to attract attention.', '그의 행동은 의도적이었고 관심을 끌기 위한 것이었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('delicate', '섬세한', '[{"pos": "a.", "ko": "섬세한, 정교한"}, {"pos": "a.", "ko": "연약한, 깨지기 쉬운"}, {"pos": "a.", "ko": "민감한, 다루기 어려운"}]'::jsonb, 'The artist used delicate brushstrokes to create a soft effect.', '그 화가는 부드러운 효과를 내기 위해 섬세한 붓질을 사용했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('delight', '기쁨', '[{"pos": "n.", "ko": "기쁨, 즐거움"}, {"pos": "v.", "ko": "기쁘게 하다, 즐겁게 하다"}]'::jsonb, 'Her smile filled the room with delight and warmth.', '그녀의 미소는 방 안을 기쁨과 따뜻함으로 가득 채웠다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deliver', '배달하다', '[{"pos": "v.", "ko": "배달하다, 전달하다"}, {"pos": "v.", "ko": "연설하다, 강연하다"}, {"pos": "v.", "ko": "(아기를) 분만하다"}, {"pos": "v.", "ko": "(약속 등을) 이행하다"}]'::jsonb, 'The store will deliver your order to your house by tomorrow.', '가게에서 내일까지 주문한 물건을 집으로 배달해 줄 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('delude', '속이다', '[{"pos": "v.", "ko": "속이다, 잘못 믿게 하다"}, {"pos": "v.", "ko": "착각하게 만들다"}]'::jsonb, 'He tried to delude his friends into believing his story was true.', '그는 친구들을 속여 자신의 이야기가 진짜라고 믿게 하려 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deluxe', '고급의', '[{"pos": "a.", "ko": "고급의, 호화로운"}]'::jsonb, 'They stayed at a deluxe hotel during their vacation.', '그들은 휴가 동안 고급 호텔에 머물렀다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('demand', '요구하다', '[{"pos": "v.", "ko": "요구하다, 요청하다"}, {"pos": "n.", "ko": "요구, 요청"}, {"pos": "n.", "ko": "수요"}]'::jsonb, 'The workers demand better working conditions from their employer.', '노동자들은 고용주에게 더 나은 근무 조건을 요구한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('democracy', '민주주의', '[{"pos": "n.", "ko": "민주주의, 민주정치"}, {"pos": "n.", "ko": "민주 국가"}]'::jsonb, 'Democracy allows citizens to participate in important decisions.', '민주주의는 시민들이 중요한 결정에 참여할 수 있게 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('demolish', '철거하다', '[{"pos": "v.", "ko": "철거하다, 허물다"}, {"pos": "v.", "ko": "완전히 파괴하다"}]'::jsonb, 'They will demolish the old building to make space for a park.', '그들은 공원을 만들기 위해 오래된 건물을 철거할 예정이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('demonstrate', '입증하다', '[{"pos": "v.", "ko": "입증하다, 증명하다"}, {"pos": "v.", "ko": "설명하다, 시범을 보이다"}, {"pos": "v.", "ko": "시위하다"}]'::jsonb, 'The scientist will demonstrate the results of her experiment to the class.', '과학자는 실험 결과를 반 친구들에게 입증해 보일 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dense', '빽빽한', '[{"pos": "a.", "ko": "빽빽한, 밀집한"}, {"pos": "a.", "ko": "(안개 등이) 짙은"}]'::jsonb, 'The forest was so dense that sunlight could barely reach the ground.', '숲이 너무 빽빽해서 햇빛이 거의 땅에 닿지 않았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dental', '치아의', '[{"pos": "a.", "ko": "치아의, 치과의"}]'::jsonb, 'Regular dental checkups are important for healthy teeth.', '건강한 치아를 위해 정기적인 치과 검진이 중요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deny', '부인하다', '[{"pos": "v.", "ko": "부인하다, 사실이 아니라고 하다"}, {"pos": "v.", "ko": "거절하다, 인정하지 않다"}]'::jsonb, 'She denied any involvement in the incident.', '그녀는 그 사건에 관여한 사실을 부인했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('departure', '출발', '[{"pos": "n.", "ko": "떠남, 출발"}]'::jsonb, 'Please arrive at the airport two hours before your departure.', '출발 두 시간 전에 공항에 도착해 주세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('depend', '의지하다', '[{"pos": "v.", "ko": "의지하다, 의존하다"}, {"pos": "v.", "ko": "~에 달려 있다"}]'::jsonb, 'Young children depend on their parents for care and support.', '어린 아이들은 돌봄과 지원을 위해 부모에게 의지한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('depict', '묘사하다', '[{"pos": "v.", "ko": "(그림이나 말로) 묘사하다, 그리다"}, {"pos": "v.", "ko": "(상황을) 자세히 설명하다"}]'::jsonb, 'The novel vividly depicts the struggles of people during the war.', '그 소설은 전쟁 중 사람들의 고난을 생생하게 묘사한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deplete', '고갈시키다', '[{"pos": "v.", "ko": "고갈시키다, 다 써버리다"}, {"pos": "v.", "ko": "감소시키다"}]'::jsonb, 'Overfishing can deplete fish populations in the ocean.', '남획은 바다의 어류 자원을 고갈시킬 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('depress', '우울하게 하다', '[{"pos": "v.", "ko": "우울하게 하다, 낙담시키다"}, {"pos": "v.", "ko": "불경기로 만들다, 침체시키다"}]'::jsonb, 'Bad news can sometimes depress even the happiest people.', '나쁜 소식은 아무리 행복한 사람도 우울하게 만들 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deprive', '빼앗다', '[{"pos": "v.", "ko": "빼앗다, 박탈하다"}]'::jsonb, 'No one should deprive children of their right to education.', '누구도 아이들의 교육받을 권리를 빼앗아서는 안 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('depth', '깊이', '[{"pos": "n.", "ko": "깊이, 깊은 곳"}, {"pos": "n.", "ko": "심도, 깊이 있는 내용"}]'::jsonb, 'The depth of the lake makes it dangerous for inexperienced swimmers.', '호수의 깊이 때문에 경험이 부족한 수영객에게는 위험하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('derive', '얻다', '[{"pos": "v.", "ko": "얻다, 이끌어내다"}, {"pos": "v.", "ko": "~에서 유래하다, 파생되다"}]'::jsonb, 'The company derives most of its income from online sales.', '그 회사는 수입의 대부분을 온라인 판매에서 얻는다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('descend', '내려가다', '[{"pos": "v.", "ko": "내려가다, 하강하다"}, {"pos": "v.", "ko": "내리막이 되다"}, {"pos": "v.", "ko": "(상황·감정 등이) 내려앉다"}, {"pos": "v.", "ko": "~에서 유래하다"}]'::jsonb, 'As the sun set, darkness began to descend over the city.', '해가 지자 어둠이 도시 위로 내려앉기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('describe', '묘사하다', '[{"pos": "v.", "ko": "묘사하다, 설명하다"}, {"pos": "v.", "ko": "특징을 말하다"}]'::jsonb, 'Please describe the main character in your own words.', '주인공을 네 말로 묘사해 보아라.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('desert', '사막', '[{"pos": "n.", "ko": "모래와 바위로 이루어진 사막"}, {"pos": "v.", "ko": "사람이나 장소를 버리다"}, {"pos": "v.", "ko": "의무나 책임을 저버리다"}]'::jsonb, 'The camel can survive for weeks without water in the desert.', '낙타는 사막에서 몇 주 동안 물 없이도 살 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deserve', '받을 자격이 있다', '[{"pos": "v.", "ko": "받을 자격이 있다"}, {"pos": "v.", "ko": "~할 만하다"}]'::jsonb, 'You deserve to be praised for your hard work and dedication.', '너는 노력과 헌신으로 칭찬받을 자격이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('designate', '지정하다', '[{"pos": "v.", "ko": "지정하다, 임명하다"}, {"pos": "v.", "ko": "표시하다, 나타내다"}, {"pos": "a.", "ko": "지정된, 임명된"}]'::jsonb, 'The teacher will designate a leader for each group today.', '선생님이 오늘 각 조의 조장을 지정할 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('desire', '간절히 바라다', '[{"pos": "v.", "ko": "간절히 바라다, 원하다"}, {"pos": "n.", "ko": "욕망, 소망"}]'::jsonb, 'Many students desire to enter a prestigious university.', '많은 학생들이 명문대 진학을 간절히 바란다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('despair', '절망', '[{"pos": "n.", "ko": "절망, 좌절"}, {"pos": "v.", "ko": "절망하다, 희망을 잃다"}]'::jsonb, 'She fell into despair after hearing the disappointing news.', '실망스러운 소식을 듣고 그녀는 절망에 빠졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('desperate', '절박한', '[{"pos": "a.", "ko": "절박한, 필사적인"}, {"pos": "a.", "ko": "절망적인, 심각한"}]'::jsonb, 'He made a desperate attempt to save his friend from danger.', '그는 친구를 위험에서 구하기 위해 필사적으로 노력했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('despise', '경멸하다', '[{"pos": "v.", "ko": "경멸하다, 얕보다"}]'::jsonb, 'You should not despise others just because they are different.', '다르다는 이유로 다른 사람을 경멸해서는 안 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('despite', '~에도 불구하고', '[{"pos": "prep.", "ko": "~에도 불구하고"}]'::jsonb, 'Despite the heavy rain, the soccer match continued as planned.', '비가 많이 왔지만 축구 경기는 예정대로 진행됐다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('destination', '목적지', '[{"pos": "n.", "ko": "목적지, 행선지"}]'::jsonb, 'The train will arrive at its final destination in two hours.', '기차는 두 시간 후에 최종 목적지에 도착할 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('destiny', '운명', '[{"pos": "n.", "ko": "운명, 숙명"}]'::jsonb, 'Many believe that everyone has a unique destiny to fulfill.', '많은 사람들은 모두가 이룰 고유한 운명을 가지고 있다고 믿는다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('destroy', '파괴하다', '[{"pos": "v.", "ko": "파괴하다, 부수다"}, {"pos": "v.", "ko": "(계획, 삶 등을) 망치다"}]'::jsonb, 'The earthquake destroyed many buildings in the city center.', '지진으로 도심의 많은 건물이 파괴되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('detach', '떼어내다', '[{"pos": "v.", "ko": "떼어내다, 분리하다"}, {"pos": "v.", "ko": "파견하다"}]'::jsonb, 'You should detach the label from the bottle before recycling it.', '재활용하기 전에 병에서 라벨을 떼어내야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('detail', '세부 사항', '[{"pos": "n.", "ko": "세부 사항, 작은 부분"}, {"pos": "n.", "ko": "상세 정보"}, {"pos": "v.", "ko": "상술하다, 자세히 설명하다"}]'::jsonb, 'Every detail of the plan was carefully reviewed by the team.', '계획의 모든 세부 사항이 팀에 의해 꼼꼼히 검토되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('detect', '발견하다', '[{"pos": "v.", "ko": "발견하다, 감지하다"}, {"pos": "v.", "ko": "알아내다, 탐지하다"}]'::jsonb, 'The machine can detect even the smallest changes in temperature.', '그 기계는 아주 작은 온도 변화도 발견할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('detergent', '세제', '[{"pos": "n.", "ko": "세제, 세정제"}, {"pos": "a.", "ko": "세정력이 있는"}]'::jsonb, 'Use a mild detergent to wash delicate clothes by hand.', '섬세한 옷은 부드러운 세제로 손세탁하세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
