INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('devote', '바치다', '[{"pos": "v.", "ko": "(시간, 노력 등을) 바치다"}, {"pos": "v.", "ko": "헌신하다, 전념하다"}]'::jsonb, 'She devoted most of her free time to volunteering at the shelter.', '그녀는 대부분의 자유 시간을 보호소에서 봉사하는 데 바쳤다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
