INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('diameter', '지름', '[{"pos": "n.", "ko": "지름, 직경"}]'::jsonb, 'The diameter of the circle is twice as long as its radius.', '원의 지름은 반지름의 두 배이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dictator', '독재자', '[{"pos": "n.", "ko": "독재자"}]'::jsonb, 'A dictator often rules the country without regard for the people''s opinions.', '독재자는 종종 국민의 의견을 무시한 채 나라를 통치한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
