INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dignity', '위엄', '[{"pos": "n.", "ko": "위엄, 품위"}, {"pos": "n.", "ko": "존엄성"}]'::jsonb, 'She handled the difficult situation with calmness and dignity.', '그녀는 어려운 상황을 침착함과 위엄 있게 대처했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
