INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dimension', '치수', '[{"pos": "n.", "ko": "(길이, 높이, 폭 등의) 치수"}, {"pos": "n.", "ko": "특성, 측면"}, {"pos": "n.", "ko": "차원"}]'::jsonb, 'Please measure the dimension of the table before buying a new one.', '새로 살 테이블을 사기 전에 치수를 재세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
