INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dine', '식사하다', '[{"pos": "v.", "ko": "식사하다, 만찬을 들다"}]'::jsonb, 'They decided to dine at a fancy restaurant for their anniversary.', '그들은 기념일을 맞아 고급 레스토랑에서 식사하기로 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
