INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('disciple', '제자', '[{"pos": "n.", "ko": "제자, 문하생"}, {"pos": "n.", "ko": "추종자"}]'::jsonb, 'The teacher inspired his disciple to follow his path in science.', '그 선생님은 제자가 과학자의 길을 걷도록 영감을 주었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
