INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('discriminate', '차별하다', '[{"pos": "v.", "ko": "차별하다, 구별하여 대우하다"}, {"pos": "v.", "ko": "식별하다, 구분하다"}]'::jsonb, 'It is illegal to discriminate against someone because of their race.', '인종을 이유로 누군가를 차별하는 것은 불법이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
