INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('electricity', '전기', '[{"pos": "n.", "ko": "전기"}, {"pos": "n.", "ko": "전류"}]'::jsonb, 'Many rural areas still lack access to reliable electricity.', '많은 시골 지역은 아직도 안정적인 전기에 접근하지 못한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('electronic', '전자 장치의', '[{"pos": "a.", "ko": "전자 장치의, 전자 공학의"}, {"pos": "a.", "ko": "전자에 관한"}]'::jsonb, 'He bought an electronic dictionary to help with his English studies.', '그는 영어 공부를 위해 전자사전을 샀다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('elegant', '우아한', '[{"pos": "a.", "ko": "우아한, 고상한"}, {"pos": "a.", "ko": "세련된, 품위 있는"}]'::jsonb, 'He wore an elegant suit to the important meeting.', '그는 중요한 회의에 우아한 정장을 입고 갔다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('elementary', '기초의', '[{"pos": "a.", "ko": "기초의, 초보의"}, {"pos": "a.", "ko": "초등의"}]'::jsonb, 'He learned the elementary rules of chess before playing his first game.', '그는 첫 경기를 두기 전에 체스의 기초 규칙을 배웠다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('eligible', '자격이 있는', '[{"pos": "a.", "ko": "자격이 있는, 적격의"}]'::jsonb, 'Only students with good grades are eligible for the scholarship.', '성적이 좋은 학생만이 그 장학금에 자격이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('eliminate', '제거하다', '[{"pos": "v.", "ko": "제거하다, 없애다"}, {"pos": "v.", "ko": "탈락시키다"}]'::jsonb, 'The company plans to eliminate unnecessary expenses this year.', '그 회사는 올해 불필요한 지출을 제거할 계획이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('eloquent', '유창한', '[{"pos": "a.", "ko": "웅변의, 표현이 유창한"}, {"pos": "a.", "ko": "감동을 주는"}]'::jsonb, 'Her eloquent speech inspired everyone in the audience.', '그녀의 유창한 연설은 청중 모두에게 영감을 주었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('embarrassed', '당황한', '[{"pos": "a.", "ko": "당황한, 난처한"}, {"pos": "a.", "ko": "어색한"}]'::jsonb, 'She felt embarrassed when she forgot her lines on stage.', '그녀는 무대에서 대사를 잊어버려 당황했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('embed', '박다', '[{"pos": "v.", "ko": "깊이 박다, 끼워 넣다"}, {"pos": "v.", "ko": "(생각·감정 등을) 마음에 심다"}]'::jsonb, 'The artist embedded small jewels into the surface of the sculpture.', '그 예술가는 조각 표면에 작은 보석을 박았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('embody', '구현하다', '[{"pos": "v.", "ko": "구체화하다, 구현하다"}, {"pos": "v.", "ko": "포함하다, 담다"}]'::jsonb, 'The new law embodies the values of equality and fairness.', '새 법은 평등과 공정의 가치를 구현한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('embrace', '껴안다', '[{"pos": "v.", "ko": "껴안다, 포옹하다"}, {"pos": "v.", "ko": "받아들이다, 수용하다"}, {"pos": "n.", "ko": "포옹"}, {"pos": "n.", "ko": "수용, 받아들임"}]'::jsonb, 'The mother warmly embraced her child after a long day.', '엄마는 긴 하루가 끝난 후 아이를 따뜻하게 껴안았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emerge', '나타나다', '[{"pos": "v.", "ko": "나타나다, 드러나다"}, {"pos": "v.", "ko": "(사실 등이) 알려지다, 부각되다"}]'::jsonb, 'A new leader emerged after the company faced several challenges.', '회사가 여러 어려움을 겪은 후 새로운 리더가 나타났다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emergency', '비상 상황', '[{"pos": "n.", "ko": "비상 상황, 긴급 사태"}, {"pos": "n.", "ko": "위급함"}]'::jsonb, 'In case of an emergency, follow the instructions given by the staff.', '비상 상황에는 직원의 안내에 따라야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emit', '내뿜다', '[{"pos": "v.", "ko": "내뿜다, 방출하다"}, {"pos": "v.", "ko": "(소리·빛 등을) 내다"}]'::jsonb, 'The factory emits smoke into the air, causing pollution.', '그 공장은 연기를 내뿜어 대기 오염을 일으킨다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emotion', '감정', '[{"pos": "n.", "ko": "감정, 정서"}]'::jsonb, 'He tried to hide his emotion during the farewell ceremony.', '그는 이별식에서 자신의 감정을 숨기려 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empathize', '공감하다', '[{"pos": "v.", "ko": "공감하다, 감정 이입하다"}]'::jsonb, 'It is important to empathize with others when they are struggling.', '다른 사람이 힘들어할 때 공감해 주는 것이 중요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emperor', '황제', '[{"pos": "n.", "ko": "황제, 제왕"}]'::jsonb, 'The emperor ruled the vast empire for over thirty years.', '황제는 30년 넘게 거대한 제국을 다스렸다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emphasize', '강조하다', '[{"pos": "v.", "ko": "강조하다, 두드러지게 하다"}, {"pos": "v.", "ko": "중요하게 여기다"}, {"pos": "v.", "ko": "강하게 발음하다"}]'::jsonb, 'The coach emphasized the need for teamwork before the game started.', '감독은 경기가 시작되기 전에 팀워크의 필요성을 강조했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empirical', '경험에 의한', '[{"pos": "a.", "ko": "경험에 의한, 실험에 근거한"}, {"pos": "a.", "ko": "관찰을 바탕으로 한"}, {"pos": "a.", "ko": "실증적인"}]'::jsonb, 'The scientist collected empirical data to support her new theory.', '그 과학자는 자신의 새로운 이론을 뒷받침하기 위해 경험적 자료를 수집했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('employ', '고용하다', '[{"pos": "v.", "ko": "고용하다, 일자리를 주다"}, {"pos": "v.", "ko": "(방법·기술 등을) 사용하다"}, {"pos": "v.", "ko": "시간을 쓰다"}]'::jsonb, 'The company decided to employ more workers for the new project.', '그 회사는 새 프로젝트를 위해 더 많은 직원을 고용하기로 결정했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empower', '권한을 주다', '[{"pos": "v.", "ko": "권한을 주다, 힘을 실어주다"}, {"pos": "v.", "ko": "자율성을 높이다"}, {"pos": "v.", "ko": "허락하다, 허가하다"}]'::jsonb, 'The program aims to empower students to make their own decisions.', '그 프로그램은 학생들에게 스스로 결정할 수 있는 권한을 주는 것을 목표로 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enable', '가능하게 하다', '[{"pos": "v.", "ko": "가능하게 하다, 할 수 있게 해 주다"}, {"pos": "v.", "ko": "허용하다, 허락하다"}]'::jsonb, 'This new technology will enable doctors to treat patients more effectively.', '이 새로운 기술은 의사들이 환자를 더 효과적으로 치료할 수 있게 해 줄 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enact', '제정하다', '[{"pos": "v.", "ko": "법으로 제정하다, 입법하다"}, {"pos": "v.", "ko": "실행하다, 시행하다"}, {"pos": "v.", "ko": "연기하다, 연출하다"}]'::jsonb, 'The government plans to enact a new law to protect the environment.', '정부는 환경을 보호하기 위한 새로운 법을 제정할 계획이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enchant', '매혹하다', '[{"pos": "v.", "ko": "매혹하다, 황홀하게 하다"}, {"pos": "v.", "ko": "마법을 걸다"}]'::jsonb, 'The beautiful scenery seemed to enchant everyone who visited the place.', '아름다운 풍경은 그곳을 방문한 모든 사람을 매혹시킨 듯했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('encircle', '둘러싸다', '[{"pos": "v.", "ko": "둘러싸다, 에워싸다"}, {"pos": "v.", "ko": "포위하다"}]'::jsonb, 'Tall trees encircle the small village, protecting it from strong winds.', '키 큰 나무들이 작은 마을을 둘러싸서 강한 바람으로부터 보호한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enclose', '둘러싸다', '[{"pos": "v.", "ko": "둘러싸다, 에워싸다"}, {"pos": "v.", "ko": "동봉하다, 함께 넣다"}]'::jsonb, 'A high fence was built to enclose the playground for safety.', '안전을 위해 놀이터를 둘러싸는 높은 울타리가 세워졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('encounter', '직면하다', '[{"pos": "v.", "ko": "(문제 등에) 직면하다, 맞닥뜨리다"}, {"pos": "v.", "ko": "우연히 만나다"}, {"pos": "n.", "ko": "(예상 밖의) 만남, 조우"}]'::jsonb, 'You may encounter many difficulties when starting a new business.', '새로운 사업을 시작할 때 많은 어려움에 직면할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('encourage', '격려하다', '[{"pos": "v.", "ko": "용기를 북돋우다, 격려하다"}, {"pos": "v.", "ko": "장려하다, 촉진하다"}, {"pos": "v.", "ko": "응원하다"}]'::jsonb, 'Parents should encourage their children to try new activities.', '부모는 자녀가 새로운 활동에 도전하도록 격려해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('endanger', '위태롭게 하다', '[{"pos": "v.", "ko": "위태롭게 하다, 위험에 빠뜨리다"}]'::jsonb, 'Pollution can endanger the lives of many animals in the forest.', '오염은 숲에 사는 많은 동물들의 생명을 위태롭게 할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('endeavor', '노력', '[{"pos": "n.", "ko": "노력, 시도"}, {"pos": "v.", "ko": "노력하다, 애쓰다"}]'::jsonb, 'Her endeavor to improve her English skills was finally successful.', '그녀의 영어 실력을 향상시키려는 노력이 마침내 결실을 맺었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('endow', '기부하다', '[{"pos": "v.", "ko": "기부하다, 부여하다"}, {"pos": "v.", "ko": "(재능·특성을) 타고나다"}]'::jsonb, 'The university was endowed with a large sum for scholarships.', '그 대학은 장학금 용도로 많은 기부금을 받았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('endure', '견디다', '[{"pos": "v.", "ko": "견디다, 참다"}, {"pos": "v.", "ko": "오래가다, 지속하다"}]'::jsonb, 'She had to endure many hardships to achieve her dream.', '그녀는 꿈을 이루기 위해 많은 고난을 견뎌야 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('engage', '참여하다', '[{"pos": "v.", "ko": "참여하다, 관여하다"}, {"pos": "v.", "ko": "(주의를) 끌다, 사로잡다"}, {"pos": "v.", "ko": "약혼하다"}]'::jsonb, 'Students are encouraged to engage in various school activities.', '학생들은 다양한 학교 활동에 참여하도록 권장된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('engross', '몰두하게 하다', '[{"pos": "v.", "ko": "몰두하게 하다, 열중하게 하다"}, {"pos": "v.", "ko": "(시장·상품을) 독점하다"}]'::jsonb, 'The novel engrossed her so much that she read it in one day.', '그 소설에 너무 몰두해서 그녀는 하루 만에 다 읽었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enhance', '향상시키다', '[{"pos": "v.", "ko": "향상시키다, 높이다"}, {"pos": "v.", "ko": "(가치·질을) 증대하다"}]'::jsonb, 'Regular exercise can enhance your physical and mental health.', '규칙적인 운동은 신체적·정신적 건강을 향상시킬 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enlightenment', '깨달음', '[{"pos": "n.", "ko": "깨달음, 계몽"}, {"pos": "n.", "ko": "지식의 확장"}]'::jsonb, 'Traveling to new places can bring enlightenment and new perspectives.', '새로운 곳을 여행하면 깨달음과 새로운 시각을 얻을 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enlist', '입대하다', '[{"pos": "v.", "ko": "입대하다, 군에 들어가다"}, {"pos": "v.", "ko": "(협조·지지를) 얻다, 요청하다"}]'::jsonb, 'He decided to enlist in the army after graduating from high school.', '그는 고등학교를 졸업한 후 군에 입대하기로 결정했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enormous', '거대한', '[{"pos": "a.", "ko": "거대한, 엄청난"}, {"pos": "a.", "ko": "막대한"}]'::jsonb, 'The company made an enormous profit last year.', '그 회사는 지난해에 거대한 이익을 냈다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enrich', '풍부하게 하다', '[{"pos": "v.", "ko": "풍부하게 하다, 질을 높이다"}, {"pos": "v.", "ko": "부유하게 하다"}]'::jsonb, 'Reading a variety of books can enrich your vocabulary and knowledge.', '다양한 책을 읽으면 어휘와 지식을 풍부하게 할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enroll', '등록하다', '[{"pos": "v.", "ko": "등록하다, 명부에 올리다"}, {"pos": "v.", "ko": "가입하다"}]'::jsonb, 'You need to enroll in the course before the deadline.', '마감일 전에 그 강좌에 등록해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
