INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('entail', '수반하다', '[{"pos": "v.", "ko": "수반하다, 필요로 하다"}, {"pos": "v.", "ko": "(논리적으로) 의미하다"}]'::jsonb, 'Success in this job will entail a lot of hard work and dedication.', '이 일에서 성공하려면 많은 노력과 헌신이 필요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enterprise', '기업', '[{"pos": "n.", "ko": "기업, 회사"}, {"pos": "n.", "ko": "진취성, 적극성"}, {"pos": "n.", "ko": "사업, 계획"}]'::jsonb, 'The new enterprise quickly became one of the leading companies in the industry.', '그 신생 기업은 곧 업계의 선두 기업 중 하나가 되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('entertain', '즐겁게 하다', '[{"pos": "v.", "ko": "즐겁게 하다"}, {"pos": "v.", "ko": "환대하다, 대접하다"}]'::jsonb, 'The magician entertained the children with amazing tricks.', '마술사는 놀라운 묘기로 아이들을 즐겁게 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enthusiasm', '열정', '[{"pos": "n.", "ko": "열정, 열의"}, {"pos": "n.", "ko": "열광"}]'::jsonb, 'Her enthusiasm for science inspired her classmates to study harder.', '그녀의 과학에 대한 열정은 반 친구들에게 더 열심히 공부하도록 자극을 주었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('entire', '전체의', '[{"pos": "a.", "ko": "전체의, 전부의"}, {"pos": "a.", "ko": "완전한, 온전한"}]'::jsonb, 'He read the entire book in just two days.', '그는 이틀 만에 책 전체를 다 읽었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('entitle', '자격을 주다', '[{"pos": "v.", "ko": "자격을 주다, 권리를 주다"}, {"pos": "v.", "ko": "제목을 붙이다"}]'::jsonb, 'Students who complete the course are entitled to receive a certificate.', '과정을 마친 학생들은 자격증을 받을 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
