INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('envy', '질투', '[{"pos": "n.", "ko": "질투, 선망"}, {"pos": "v.", "ko": "부러워하다, 질투하다"}]'::jsonb, 'She could not hide her envy when she saw her friend''s new phone.', '그녀는 친구의 새 휴대폰을 보고 질투를 감추지 못했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('epidemic', '유행병', '[{"pos": "n.", "ko": "유행병, 전염병"}, {"pos": "a.", "ko": "유행성의, 전염성의"}]'::jsonb, 'The city took action to control the epidemic and protect its citizens.', '그 도시는 유행병을 막고 시민들을 보호하기 위해 조치를 취했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
