INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('equivalent', '동등한', '[{"pos": "a.", "ko": "동등한, 대등한"}, {"pos": "a.", "ko": "...에 상당하는"}, {"pos": "n.", "ko": "동등한 것, 등가물"}]'::jsonb, 'One hour of jogging is equivalent to about two hours of walking.', '조깅 한 시간은 걷기 두 시간과 동등하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
