INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('extend', '연장하다', '[{"pos": "v.", "ko": "연장하다, 늘리다"}, {"pos": "v.", "ko": "뻗다, 내밀다"}, {"pos": "v.", "ko": "(도움, 친절을) 베풀다, 제공하다"}]'::jsonb, 'The company decided to extend the deadline for the project by one week.', '그 회사는 프로젝트 마감일을 일주일 연장하기로 결정했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
