INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('fiber', '섬유', '[{"pos": "n.", "ko": "섬유, 섬유질"}, {"pos": "n.", "ko": "(근육·신경 등의) 섬유"}]'::jsonb, 'Eating foods rich in fiber is good for your digestion.', '섬유질이 풍부한 음식을 먹으면 소화에 좋다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
