INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('fierce', '사나운', '[{"pos": "a.", "ko": "사나운, 맹렬한"}, {"pos": "a.", "ko": "격렬한"}]'::jsonb, 'The fierce lion protected its territory from other animals.', '사나운 사자가 자신의 영역을 다른 동물들로부터 지켰다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
