INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('flavor', '맛', '[{"pos": "n.", "ko": "맛, 풍미"}, {"pos": "n.", "ko": "특색, 분위기"}]'::jsonb, 'This soup has a rich flavor because of the fresh herbs.', '이 수프는 신선한 허브 덕분에 맛이 풍부하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
