INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('gymnastics', '체조', '[{"pos": "n.", "ko": "체조, 체조 경기"}]'::jsonb, 'She practices gymnastics every day to improve her balance and strength.', '그녀는 균형과 체력을 기르기 위해 매일 체조를 연습한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
