INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('indicate', '가리키다', '[{"pos": "v.", "ko": "가리키다"}, {"pos": "v.", "ko": "나타내다"}, {"pos": "v.", "ko": "암시하다"}]'::jsonb, 'The sign on the wall indicates the direction to the library.', '벽에 붙은 표지판이 도서관 가는 방향을 가리킨다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
