INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('individual', '개별의', '[{"pos": "a.", "ko": "개별의"}, {"pos": "a.", "ko": "독특한"}, {"pos": "n.", "ko": "개인"}, {"pos": "n.", "ko": "사람"}]'::jsonb, 'Each student will receive individual attention from the teacher.', '각 학생은 교사로부터 개별적인 지도를 받게 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('induce', '설득하다', '[{"pos": "v.", "ko": "설득하다"}, {"pos": "v.", "ko": "야기하다"}, {"pos": "v.", "ko": "유도하다"}]'::jsonb, 'The manager tried to induce the team to work overtime for the project.', '관리자는 팀이 프로젝트를 위해 야근하도록 설득했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('indulge', '충족시키다', '[{"pos": "v.", "ko": "(욕구·기호를) 충족시키다"}, {"pos": "v.", "ko": "(남을) 마음대로 하게 하다"}, {"pos": "v.", "ko": "(나쁜 습관에) 빠지다"}]'::jsonb, 'Sometimes, it is okay to indulge your desire for sweet foods.', '가끔은 단 음식을 먹고 싶은 욕구를 충족시켜도 괜찮다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('industry', '산업', '[{"pos": "n.", "ko": "산업"}, {"pos": "n.", "ko": "공업, 제조업"}, {"pos": "n.", "ko": "근면"}]'::jsonb, 'The automobile industry is facing new challenges these days.', '요즘 자동차 산업은 새로운 도전에 직면해 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
