INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('infant', '유아', '[{"pos": "n.", "ko": "유아, 아기"}, {"pos": "a.", "ko": "유아의, 아기의"}, {"pos": "a.", "ko": "초기의"}]'::jsonb, 'The infant smiled when she heard her mother''s voice.', '아기는 엄마 목소리를 듣고 미소를 지었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('infection', '감염', '[{"pos": "n.", "ko": "감염"}, {"pos": "n.", "ko": "오염"}]'::jsonb, 'The doctor prescribed antibiotics to treat the infection.', '의사는 감염을 치료하기 위해 항생제를 처방했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inference', '추론', '[{"pos": "n.", "ko": "추론"}, {"pos": "n.", "ko": "추정, 추측"}]'::jsonb, 'Your inference about the story''s ending was correct.', '이야기 결말에 대한 네 추론이 맞았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('infinite', '무한한', '[{"pos": "a.", "ko": "무한한"}, {"pos": "a.", "ko": "끝없는"}]'::jsonb, 'The possibilities for the future seem infinite to young people.', '미래의 가능성은 젊은이들에게 무한하게 느껴진다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
