INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inherent', '내재된', '[{"pos": "a.", "ko": "내재된"}, {"pos": "a.", "ko": "고유의"}, {"pos": "a.", "ko": "타고난"}]'::jsonb, 'There are inherent risks in every new business venture.', '모든 새로운 사업에는 내재된 위험이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inherit', '상속받다', '[{"pos": "v.", "ko": "상속받다"}, {"pos": "v.", "ko": "물려받다"}, {"pos": "v.", "ko": "유전되다"}]'::jsonb, 'She will inherit her grandmother''s house after she graduates.', '그녀는 졸업 후 할머니의 집을 상속받을 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('initial', '처음의', '[{"pos": "a.", "ko": "처음의, 최초의"}, {"pos": "n.", "ko": "머리글자, 이니셜"}]'::jsonb, 'Her initial reaction to the news was one of surprise and disbelief.', '그 소식을 처음 들었을 때 그녀는 놀라고 믿지 못했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inject', '주사하다', '[{"pos": "v.", "ko": "주사하다, 주입하다"}, {"pos": "v.", "ko": "(새로운 요소를) 도입하다"}]'::jsonb, 'Doctors must inject the vaccine into the patient''s arm carefully.', '의사들은 환자의 팔에 백신을 조심스럽게 주사해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('injure', '다치게 하다', '[{"pos": "v.", "ko": "상처를 입히다, 다치게 하다"}, {"pos": "v.", "ko": "(감정·명예 등을) 손상시키다, 해치다"}]'::jsonb, 'He did not want to injure his friend during the soccer match.', '그는 축구 경기 중에 친구를 다치게 하고 싶지 않았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('innate', '선천적인', '[{"pos": "a.", "ko": "선천적인, 타고난"}]'::jsonb, 'Some people have an innate talent for music from a young age.', '어떤 사람들은 어릴 때부터 선천적으로 음악에 재능이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inner', '내부의', '[{"pos": "a.", "ko": "내부의, 안쪽의"}, {"pos": "a.", "ko": "내면의, 마음속의"}]'::jsonb, 'The inner walls of the castle were built to protect against attacks.', '성의 내부 벽은 공격을 막기 위해 지어졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('innermost', '가장 안쪽의', '[{"pos": "a.", "ko": "가장 안쪽의, 가장 깊은"}]'::jsonb, 'She kept her innermost thoughts hidden from everyone.', '그녀는 자신의 가장 깊은 생각을 아무에게도 털어놓지 않았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('innocence', '결백', '[{"pos": "n.", "ko": "결백, 무죄"}, {"pos": "n.", "ko": "순수함, 순진함"}]'::jsonb, 'The lawyer argued strongly for his client''s innocence in court.', '변호사는 법정에서 의뢰인의 결백을 강하게 주장했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('innovation', '혁신', '[{"pos": "n.", "ko": "혁신, 새로움"}, {"pos": "n.", "ko": "새로운 고안, 신기술"}]'::jsonb, 'Innovation in technology has changed the way we communicate.', '기술 혁신으로 우리의 소통 방식이 달라졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inquire', '묻다', '[{"pos": "v.", "ko": "묻다, 질문하다"}, {"pos": "v.", "ko": "조사하다, 알아보다"}]'::jsonb, 'She called the office to inquire about the application process.', '그녀는 지원 절차를 묻기 위해 사무실에 전화했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('insane', '미친', '[{"pos": "a.", "ko": "정신 이상의, 미친"}, {"pos": "a.", "ko": "터무니없는, 비상식적인"}]'::jsonb, 'It would be insane to try climbing that mountain without any experience.', '아무런 경험 없이 그 산을 오르려는 것은 미친 짓일 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inseparable', '떨어질 수 없는', '[{"pos": "a.", "ko": "떨어질 수 없는, 불가분의"}, {"pos": "a.", "ko": "매우 친한"}]'::jsonb, 'The two friends have been inseparable since they met in middle school.', '그 두 친구는 중학교에서 만난 이후로 떨어질 수 없을 만큼 친했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('insert', '삽입하다', '[{"pos": "v.", "ko": "삽입하다, 끼워 넣다"}, {"pos": "v.", "ko": "(문서 등에) 말을 써 넣다, 덧붙이다"}]'::jsonb, 'Please insert your card into the machine to begin the transaction.', '거래를 시작하려면 카드를 기계에 삽입하세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('insight', '통찰력', '[{"pos": "n.", "ko": "통찰력, 식견"}, {"pos": "n.", "ko": "이해, 간파"}]'::jsonb, 'Her insight into human behavior helped solve the problem quickly.', '그녀의 인간 행동에 대한 통찰력 덕분에 문제를 빨리 해결할 수 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('insist', '주장하다', '[{"pos": "v.", "ko": "주장하다, 고집하다"}, {"pos": "v.", "ko": "(강하게) 요구하다"}]'::jsonb, 'He insisted that he was telling the truth despite the evidence.', '그는 증거에도 불구하고 자신이 진실을 말하고 있다고 주장했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
