INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('microscope', '현미경', '[{"pos": "n.", "ko": "현미경"}]'::jsonb, 'She observed the tiny cells through a powerful microscope.', '그녀는 강력한 현미경으로 작은 세포들을 관찰했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
