INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('mortgage', '주택 담보 대출', '[{"pos": "n.", "ko": "주택 담보 대출, 저당"}, {"pos": "v.", "ko": "(재산을) 저당 잡히다"}]'::jsonb, 'He took out a mortgage to buy his first house.', '그는 첫 집을 사기 위해 주택 담보 대출을 받았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
