INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('nomad', '유목민', '[{"pos": "n.", "ko": "유목민, 방랑자"}]'::jsonb, 'The nomad moved from place to place in search of water and food.', '그 유목민은 물과 음식을 찾아 이곳저곳을 옮겨 다녔다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
