INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('notify', '알리다', '[{"pos": "v.", "ko": "알리다, 통보하다"}]'::jsonb, 'Please notify me if there are any changes to the schedule.', '일정에 변경이 있으면 저에게 알려주세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('notion', '생각', '[{"pos": "n.", "ko": "생각, 관념"}, {"pos": "n.", "ko": "개념"}]'::jsonb, 'She had a clear notion of what she wanted to achieve.', '그녀는 자신이 이루고 싶은 것에 대한 분명한 생각이 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
