INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('novel', '소설', '[{"pos": "n.", "ko": "(장편) 소설"}, {"pos": "a.", "ko": "새로운, 신기한"}]'::jsonb, 'She spent the weekend reading a novel by her favorite author.', '그녀는 주말 내내 좋아하는 작가의 소설을 읽었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
