INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('partial', '부분적인', '[{"pos": "a.", "ko": "부분적인, 일부분의"}, {"pos": "a.", "ko": "불공평한, 편파적인"}, {"pos": "a.", "ko": "특히 좋아하는, 편애하는"}]'::jsonb, 'We only have partial information about the new policy.', '우리는 새 정책에 대해 부분적인 정보만 가지고 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
