INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('passerby', '지나가는 사람', '[{"pos": "n.", "ko": "지나가는 사람"}, {"pos": "n.", "ko": "통행인"}]'::jsonb, 'A passerby helped the child cross the busy street safely.', '지나가는 사람이 아이가 복잡한 길을 안전하게 건너도록 도와주었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('passion', '열정', '[{"pos": "n.", "ko": "열정"}, {"pos": "n.", "ko": "애착"}]'::jsonb, 'She spoke about her passion for music during the interview.', '그녀는 인터뷰에서 음악에 대한 열정을 이야기했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('passive', '수동적인', '[{"pos": "a.", "ko": "수동적인"}, {"pos": "a.", "ko": "소극적인"}]'::jsonb, 'A passive attitude can make it hard to achieve your goals.', '수동적인 태도는 목표를 이루기 어렵게 만들 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('paste', '풀', '[{"pos": "n.", "ko": "풀"}, {"pos": "v.", "ko": "붙이다"}]'::jsonb, 'Use some paste to attach the poster to the wall.', '포스터를 벽에 붙이려면 풀을 사용해라.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('pasture', '목초지', '[{"pos": "n.", "ko": "목초지"}, {"pos": "n.", "ko": "방목장"}]'::jsonb, 'Cows were grazing peacefully in the green pasture.', '소들이 푸른 목초지에서 평화롭게 풀을 뜯고 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
