INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('patent', '특허', '[{"pos": "n.", "ko": "특허"}, {"pos": "v.", "ko": "특허를 얻다"}, {"pos": "a.", "ko": "특허의"}]'::jsonb, 'She applied for a patent for her new invention last year.', '그녀는 작년에 자신의 새 발명품에 대해 특허를 신청했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('patient', '참을성 있는', '[{"pos": "a.", "ko": "참을성 있는, 인내심 있는"}, {"pos": "n.", "ko": "환자"}]'::jsonb, 'A good teacher is always patient with students who learn slowly.', '좋은 선생님은 느리게 배우는 학생들에게 항상 참을성이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('patriot', '애국자', '[{"pos": "n.", "ko": "애국자"}]'::jsonb, 'A true patriot always puts the country''s interests first.', '진정한 애국자는 언제나 나라의 이익을 우선시한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
