INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('patron', '후원자', '[{"pos": "n.", "ko": "후원자, 지원자"}, {"pos": "n.", "ko": "고객, 단골"}]'::jsonb, 'The museum was able to open a new gallery thanks to its generous patron.', '박물관은 후원자의 도움으로 새 전시실을 열 수 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
