INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('pavement', '인도', '[{"pos": "n.", "ko": "인도, 보도"}]'::jsonb, 'Children should walk on the pavement to avoid traffic accidents.', '어린이들은 교통사고를 피하려면 인도를 걸어야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
