INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('positive', '긍정적인', '[{"pos": "a.", "ko": "긍정적인, 낙관적인"}, {"pos": "a.", "ko": "확실한, 명확한"}, {"pos": "a.", "ko": "양성의, 양극의"}]'::jsonb, 'Having a positive attitude can help you overcome many challenges in life.', '긍정적인 태도는 인생의 많은 어려움을 이겨내는 데 도움이 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('possess', '소유하다', '[{"pos": "v.", "ko": "소유하다, 가지고 있다"}, {"pos": "v.", "ko": "지배하다, 사로잡다"}]'::jsonb, 'You must possess a valid ID to enter the examination room.', '시험장에 들어가려면 유효한 신분증을 소지해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('possibility', '가능성', '[{"pos": "n.", "ko": "가능성, 될 수 있음"}, {"pos": "n.", "ko": "가망, 희망"}]'::jsonb, 'There is a possibility that the event will be canceled due to rain.', '비로 인해 행사가 취소될 가능성이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('post', '우편', '[{"pos": "n.", "ko": "우편, 우편물"}, {"pos": "n.", "ko": "직책, 일자리"}, {"pos": "v.", "ko": "게시하다, 올리다"}, {"pos": "v.", "ko": "우편으로 보내다"}]'::jsonb, 'I received a letter in the post from my friend yesterday.', '나는 어제 친구로부터 우편으로 편지를 받았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('postpone', '연기하다', '[{"pos": "v.", "ko": "연기하다, 미루다"}]'::jsonb, 'The meeting was postponed due to unexpected circumstances.', '예기치 못한 상황으로 회의가 연기되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('posture', '자세', '[{"pos": "n.", "ko": "자세, 몸가짐"}, {"pos": "n.", "ko": "태도, 입장"}]'::jsonb, 'Good posture is important for maintaining a healthy back.', '좋은 자세는 건강한 허리를 유지하는 데 중요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('potential', '잠재적인', '[{"pos": "a.", "ko": "잠재적인, 가능성 있는"}, {"pos": "n.", "ko": "잠재력, 가능성"}]'::jsonb, 'Every student has the potential to achieve great things.', '모든 학생은 위대한 일을 이룰 잠재력을 가지고 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('pottery', '도자기', '[{"pos": "n.", "ko": "도자기, 도기류"}, {"pos": "n.", "ko": "도예, 도자기 제조"}]'::jsonb, 'The museum displays ancient pottery from various cultures.', '그 박물관에는 여러 문화의 고대 도자기가 전시되어 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('poverty', '빈곤', '[{"pos": "n.", "ko": "빈곤, 가난"}]'::jsonb, 'Many organizations work to reduce poverty around the world.', '많은 단체들이 전 세계의 빈곤을 줄이기 위해 노력한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('precaution', '예방책', '[{"pos": "n.", "ko": "예방책, 조심"}, {"pos": "n.", "ko": "경계, 주의"}]'::jsonb, 'Wearing a seat belt is an important precaution when driving.', '운전할 때 안전벨트를 매는 것은 중요한 예방책이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('precede', '앞서다', '[{"pos": "v.", "ko": "앞서다, 선행하다"}, {"pos": "v.", "ko": "먼저 일어나다"}]'::jsonb, 'A short introduction will precede the main presentation.', '간단한 소개가 본 발표에 앞서 진행될 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('precise', '정확한', '[{"pos": "a.", "ko": "정확한, 틀림없는"}, {"pos": "a.", "ko": "정밀한, 세밀한"}]'::jsonb, 'The scientist gave a precise explanation of the experiment''s results.', '그 과학자는 실험 결과에 대해 정확하게 설명했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('predator', '포식자', '[{"pos": "n.", "ko": "포식자, 육식 동물"}, {"pos": "n.", "ko": "약탈자, 착취자"}]'::jsonb, 'The lion is a powerful predator at the top of the food chain.', '사자는 먹이사슬의 최상위에 있는 강력한 포식자이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('predecessor', '전임자', '[{"pos": "n.", "ko": "전임자, 이전의 것"}, {"pos": "n.", "ko": "선배, 선조"}]'::jsonb, 'The new manager thanked his predecessor for the helpful advice.', '신임 관리자는 전임자에게 유익한 조언에 대해 감사했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('predict', '예측하다', '[{"pos": "v.", "ko": "예측하다, 예상하다"}, {"pos": "v.", "ko": "예언하다"}]'::jsonb, 'Experts predict that the economy will improve next year.', '전문가들은 내년에 경제가 나아질 것이라고 예측한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('predominant', '두드러진', '[{"pos": "a.", "ko": "두드러진, 현저한"}, {"pos": "a.", "ko": "지배적인, 우세한"}]'::jsonb, 'English is the predominant language in international business.', '영어는 국제 비즈니스에서 두드러진 언어이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('prefer', '더 좋아하다', '[{"pos": "v.", "ko": "더 좋아하다, 선호하다"}, {"pos": "v.", "ko": "차라리 ~을 택하다"}]'::jsonb, 'Most students prefer studying in a quiet environment.', '대부분의 학생들은 조용한 환경에서 공부하는 것을 더 좋아한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('pregnant', '임신한', '[{"pos": "a.", "ko": "임신한"}, {"pos": "a.", "ko": "(의미, 중요성 등을) 내포한"}]'::jsonb, 'She discovered she was pregnant after visiting the doctor.', '그녀는 병원에 다녀온 후 임신 사실을 알게 되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
