INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('prejudice', '편견', '[{"pos": "n.", "ko": "편견, 선입견"}, {"pos": "v.", "ko": "편견을 갖게 하다"}]'::jsonb, 'We must overcome prejudice to build a fair society.', '공정한 사회를 만들기 위해 우리는 편견을 극복해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('preliminary', '예비의', '[{"pos": "a.", "ko": "예비의, 준비의"}, {"pos": "a.", "ko": "서두의, 예선의"}, {"pos": "n.", "ko": "예비, 준비, 예선전"}]'::jsonb, 'The team passed the preliminary round and moved on to the finals.', '그 팀은 예선을 통과해 결승에 진출했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('premature', '시기상조의', '[{"pos": "a.", "ko": "시기상조의, 너무 이른"}, {"pos": "a.", "ko": "조급한, 성급한"}]'::jsonb, 'The decision to cancel the event was premature and surprised many people.', '행사를 취소한 결정은 시기상조여서 많은 사람들을 놀라게 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('preoccupation', '몰두', '[{"pos": "n.", "ko": "몰두, 집착"}, {"pos": "n.", "ko": "걱정거리, 관심사"}]'::jsonb, 'Her preoccupation with her studies left her little time for friends.', '그녀는 공부에 몰두하느라 친구들과 보낼 시간이 거의 없었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
