INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('prestigious', '명성 있는', '[{"pos": "a.", "ko": "명성 있는, 명문의"}]'::jsonb, 'He graduated from a prestigious university in the United States.', '그는 미국의 명문 대학을 졸업했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
