INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('refresh', '상쾌하게 하다', '[{"pos": "v.", "ko": "상쾌하게 하다, 기운 나게 하다"}, {"pos": "v.", "ko": "새로 고치다, 새롭게 하다"}]'::jsonb, 'A short walk outside can refresh your mind during a busy day.', '바쁜 하루 중 잠깐 산책하면 머리가 상쾌해진다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('refuge', '피난처', '[{"pos": "n.", "ko": "피난처, 보호소"}, {"pos": "n.", "ko": "위안, 안식처"}]'::jsonb, 'The cave provided refuge for the hikers during the storm.', '폭풍우 속에서 동굴이 등산객들에게 피난처가 되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('refund', '환불', '[{"pos": "n.", "ko": "환불, 반환금"}, {"pos": "v.", "ko": "환불하다, 돌려주다"}]'::jsonb, 'If the product is damaged, you can request a full refund.', '제품에 하자가 있으면 전액 환불을 요청할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('refuse', '거절하다', '[{"pos": "v.", "ko": "거절하다, 거부하다"}]'::jsonb, 'She refused the invitation to the party politely.', '그녀는 파티 초대를 정중히 거절했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('regard', '여기다', '[{"pos": "v.", "ko": "~로 여기다, 간주하다"}, {"pos": "n.", "ko": "존경, 존중"}, {"pos": "v.", "ko": "응시하다, 바라보다"}]'::jsonb, 'Many people regard honesty as the most important value.', '많은 사람들이 정직을 가장 중요한 가치로 여긴다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('regime', '정권', '[{"pos": "n.", "ko": "정권, 정부 체제"}, {"pos": "n.", "ko": "(특정한) 제도, 체계"}]'::jsonb, 'The new regime introduced several economic reforms last year.', '새 정권은 지난해 여러 경제 개혁을 도입했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('region', '지역', '[{"pos": "n.", "ko": "지역, 지방"}, {"pos": "n.", "ko": "(신체의) 부위, 부분"}]'::jsonb, 'This region is famous for its beautiful mountain scenery.', '이 지역은 아름다운 산 풍경으로 유명하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('register', '등록하다', '[{"pos": "v.", "ko": "등록하다, 이름을 올리다"}, {"pos": "v.", "ko": "기록하다, 나타내다"}, {"pos": "n.", "ko": "등록부, 명부"}]'::jsonb, 'You must register for the course before the deadline.', '마감일 전에 그 강좌에 등록해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('regret', '후회하다', '[{"pos": "v.", "ko": "후회하다, 유감으로 여기다"}, {"pos": "n.", "ko": "후회, 유감"}]'::jsonb, 'He began to regret his decision after seeing the results.', '그는 결과를 보고 자신의 결정을 후회하기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('regulate', '규제하다', '[{"pos": "v.", "ko": "규제하다, 통제하다"}, {"pos": "v.", "ko": "조절하다, 조정하다"}]'::jsonb, 'The government plans to regulate the use of plastic bags.', '정부는 비닐봉투 사용을 규제할 계획이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reign', '통치하다', '[{"pos": "v.", "ko": "통치하다, 지배하다"}, {"pos": "n.", "ko": "통치 기간, 치세"}]'::jsonb, 'The queen will reign over the country for many years.', '여왕은 오랫동안 그 나라를 통치할 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reinforcement', '강화', '[{"pos": "n.", "ko": "강화, 보강"}, {"pos": "n.", "ko": "증원, 지원"}]'::jsonb, 'Positive reinforcement helps students build good habits.', '긍정적 강화는 학생들이 좋은 습관을 기르는 데 도움이 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reject', '거절하다', '[{"pos": "v.", "ko": "거절하다, 거부하다"}, {"pos": "n.", "ko": "불합격품, 거부된 것"}]'::jsonb, 'The committee decided to reject the proposal after careful review.', '위원회는 신중히 검토한 후 그 제안을 거절하기로 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('rejoice', '매우 기뻐하다', '[{"pos": "v.", "ko": "매우 기뻐하다, 환희하다"}, {"pos": "v.", "ko": "즐거워하다"}]'::jsonb, 'The students rejoiced when they heard the results of the exam.', '학생들은 시험 결과를 듣고 매우 기뻐했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('relate', '관련시키다', '[{"pos": "v.", "ko": "관련시키다, 연관 짓다"}, {"pos": "v.", "ko": "(사건 등을) 이야기하다, 설명하다"}]'::jsonb, 'It is important to relate new information to what you already know.', '새로운 정보를 이미 알고 있는 것과 관련짓는 것이 중요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('relationship', '관계', '[{"pos": "n.", "ko": "관계, 관련"}, {"pos": "n.", "ko": "(연인 사이의) 관계"}]'::jsonb, 'Trust is essential in any healthy relationship.', '신뢰는 어떤 건강한 관계에서도 필수적이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('release', '석방하다', '[{"pos": "v.", "ko": "석방하다, 놓아주다"}, {"pos": "v.", "ko": "공개하다, 발표하다"}, {"pos": "v.", "ko": "(영화, 음반 등을) 개봉하다, 발매하다"}, {"pos": "v.", "ko": "(감정, 화학 물질 등을) 표출하다, 방출하다"}, {"pos": "n.", "ko": "석방"}, {"pos": "n.", "ko": "공개, 발표"}, {"pos": "n.", "ko": "(영화, 음반 등의) 개봉, 발매"}, {"pos": "n.", "ko": "표출, 방출"}]'::jsonb, 'The government decided to release the prisoners after the negotiations.', '정부는 협상 후에 죄수들을 석방하기로 결정했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('relevant', '관련된', '[{"pos": "a.", "ko": "관련된, 관계가 있는"}]'::jsonb, 'Only relevant information should be included in your report.', '보고서에는 관련된 정보만 포함해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('relieve', '경감하다', '[{"pos": "v.", "ko": "(고통, 고민 등을) 경감하다, 완화하다"}]'::jsonb, 'Taking a short walk can relieve stress and clear your mind.', '잠깐 산책을 하면 스트레스를 경감하고 머리를 맑게 할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('religious', '종교의', '[{"pos": "a.", "ko": "종교의, 신앙과 관련된"}, {"pos": "a.", "ko": "신앙심이 깊은, 독실한"}]'::jsonb, 'Many religious festivals are celebrated around the world every year.', '전 세계에서 매년 많은 종교 축제가 열린다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('rely', '의지하다', '[{"pos": "v.", "ko": "의지하다, 믿다"}, {"pos": "v.", "ko": "신뢰하다"}]'::jsonb, 'Children often rely on their parents for support and guidance.', '아이들은 종종 부모에게 의지해 도움과 조언을 얻는다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('remain', '여전히 ~이다', '[{"pos": "v.", "ko": "여전히 ~인 상태이다"}, {"pos": "v.", "ko": "머무르다, 체류하다"}, {"pos": "v.", "ko": "남아 있다, 남다"}]'::jsonb, 'Despite the changes, the main idea remains the same.', '변화가 있었지만, 핵심 내용은 여전히 같다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('remark', '언급하다', '[{"pos": "v.", "ko": "말하다, 언급하다"}, {"pos": "n.", "ko": "발언, 논평"}]'::jsonb, 'He remarked that the weather was unusually cold for May.', '그는 5월치고 날씨가 유난히 춥다고 언급했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('remedy', '치료법', '[{"pos": "n.", "ko": "치료법, 해결책"}, {"pos": "v.", "ko": "치료하다, 바로잡다"}]'::jsonb, 'Drinking warm tea can be a simple remedy for a sore throat.', '따뜻한 차를 마시는 것은 인후통에 간단한 치료법이 될 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('remind', '상기시키다', '[{"pos": "v.", "ko": "상기시키다, 일깨워주다"}, {"pos": "v.", "ko": "생각나게 하다"}]'::jsonb, 'Can you remind me to call my friend this evening?', '오늘 저녁에 친구에게 전화하라고 나에게 상기시켜줄 수 있니?', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('remote', '외진', '[{"pos": "a.", "ko": "외진, 멀리 떨어진"}, {"pos": "a.", "ko": "(시간, 관계 등이) 먼"}, {"pos": "a.", "ko": "희박한"}, {"pos": "a.", "ko": "원격 조정의"}]'::jsonb, 'They traveled to a remote village in the mountains for research.', '그들은 연구를 위해 산속의 외진 마을로 떠났다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('remove', '제거하다', '[{"pos": "v.", "ko": "제거하다, 없애다"}, {"pos": "v.", "ko": "옮기다, 이동시키다"}]'::jsonb, 'Please remove your shoes before entering the house.', '집에 들어가기 전에 신발을 벗어 주세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('render', '~하게 만들다', '[{"pos": "v.", "ko": "~을 ~한 상태로 만들다"}, {"pos": "v.", "ko": "(도움 등을) 주다, 제공하다"}, {"pos": "v.", "ko": "(글, 그림 등으로) 표현하다, 묘사하다"}]'::jsonb, 'The loud noise rendered him unable to concentrate on his work.', '시끄러운 소음 때문에 그는 일에 집중할 수 없게 되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('renew', '갱신하다', '[{"pos": "v.", "ko": "갱신하다, 연장하다"}, {"pos": "v.", "ko": "재개하다, 다시 시작하다"}]'::jsonb, 'You need to renew your passport before it expires next month.', '다음 달에 여권이 만료되기 전에 갱신해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('renovate', '개조하다', '[{"pos": "v.", "ko": "(건물 등을) 개조하다"}, {"pos": "v.", "ko": "새롭게 하다, 개선하다"}]'::jsonb, 'They decided to renovate the old house before moving in.', '그들은 이사하기 전에 오래된 집을 개조하기로 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('renowned', '유명한', '[{"pos": "a.", "ko": "유명한, 명성이 높은"}]'::jsonb, 'She is a renowned scientist known for her groundbreaking research.', '그녀는 혁신적인 연구로 유명한 과학자이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('rent', '임대료', '[{"pos": "n.", "ko": "임대료, 집세"}, {"pos": "v.", "ko": "임대하다, 빌리다"}]'::jsonb, 'The rent for this apartment is higher than I expected.', '이 아파트의 임대료는 내가 예상한 것보다 비싸다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('repair', '수리하다', '[{"pos": "v.", "ko": "수리하다, 고치다"}, {"pos": "n.", "ko": "수리, 보수"}]'::jsonb, 'You should repair the broken window as soon as possible.', '깨진 창문은 가능한 한 빨리 수리해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('repetitive', '반복적인', '[{"pos": "a.", "ko": "반복적인, 되풀이되는"}]'::jsonb, 'The work was so repetitive that she quickly lost interest.', '그 일은 너무 반복적이어서 그녀는 금방 흥미를 잃었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
