INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shadow', '그림자', '[{"pos": "n.", "ko": "그림자, 어둠"}, {"pos": "n.", "ko": "흔적, 자취"}]'::jsonb, 'The tall tree cast a long shadow on the ground.', '키 큰 나무가 땅에 긴 그림자를 드리웠다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shallow', '얕은', '[{"pos": "a.", "ko": "얕은, 깊지 않은"}, {"pos": "a.", "ko": "피상적인, 얄팍한"}]'::jsonb, 'Be careful when swimming in the shallow part of the pool.', '수영장에서 얕은 곳에서 수영할 때는 조심해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shatter', '산산이 부수다', '[{"pos": "v.", "ko": "산산이 부수다, 산산조각 내다"}, {"pos": "v.", "ko": "(희망·신념 등을) 무너뜨리다"}]'::jsonb, 'The glass vase fell and shattered into hundreds of pieces.', '유리 꽃병이 떨어져 산산조각이 났다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shed', '흘리다', '[{"pos": "v.", "ko": "(눈물·피 등을) 흘리다"}, {"pos": "v.", "ko": "(빛·열 등을) 발하다"}, {"pos": "v.", "ko": "(잎·털 등을) 떨어뜨리다"}]'::jsonb, 'It is natural to shed tears at a touching movie scene.', '감동적인 영화 장면에서 눈물을 흘리는 것은 자연스러운 일이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shelter', '피난처', '[{"pos": "n.", "ko": "피난처, 대피소"}, {"pos": "v.", "ko": "보호하다, 숨기다"}]'::jsonb, 'The hikers found shelter in a small cave during the storm.', '등산객들은 폭풍우가 치는 동안 작은 동굴에서 피난처를 찾았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shield', '방패', '[{"pos": "n.", "ko": "방패, 보호막"}, {"pos": "v.", "ko": "보호하다, 막다"}]'::jsonb, 'The knight held up his shield to block the enemy''s attack.', '기사는 적의 공격을 막기 위해 방패를 들었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shift', '옮기다', '[{"pos": "v.", "ko": "옮기다, 이동하다"}, {"pos": "n.", "ko": "변화, 교대 근무"}]'::jsonb, 'You should shift your focus to more important tasks now.', '이제 더 중요한 일에 집중을 옮겨야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shiver', '떨다', '[{"pos": "v.", "ko": "떨다, 몸서리치다"}, {"pos": "n.", "ko": "떨림, 전율"}]'::jsonb, 'She began to shiver as the cold wind blew through the window.', '찬바람이 창문으로 들어오자 그녀는 떨기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shortage', '부족', '[{"pos": "n.", "ko": "부족, 결핍"}]'::jsonb, 'There is a severe water shortage in many parts of the country.', '국내 여러 지역에 심각한 물 부족이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shred', '찢다', '[{"pos": "v.", "ko": "갈가리 찢다, 잘게 자르다"}, {"pos": "n.", "ko": "조각, 아주 작은 양"}]'::jsonb, 'He used a machine to shred all the old documents in the office.', '그는 사무실의 오래된 문서들을 모두 기계로 찢었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shrink', '줄어들다', '[{"pos": "v.", "ko": "줄어들다, 오그라들다"}, {"pos": "v.", "ko": "(옷 등이) 수축하다"}, {"pos": "v.", "ko": "(두려움 등으로) 움츠러들다"}]'::jsonb, 'The sweater will shrink if you wash it in hot water.', '스웨터는 뜨거운 물에 세탁하면 줄어들 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shrub', '관목', '[{"pos": "n.", "ko": "관목, 덤불"}]'::jsonb, 'A small bird was hiding in the shrub near the fence.', '작은 새 한 마리가 울타리 근처 관목 속에 숨어 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shrug', '으쓱하다', '[{"pos": "v.", "ko": "(어깨를) 으쓱하다"}, {"pos": "n.", "ko": "어깨 으쓱하기"}]'::jsonb, 'He could only shrug when asked about the missing files.', '그는 분실된 파일에 대해 묻자 어깨만 으쓱했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shudder', '몸을 떨다', '[{"pos": "v.", "ko": "(공포·추위 등으로) 몸을 떨다"}, {"pos": "n.", "ko": "몸서리, 전율"}]'::jsonb, 'She couldn''t help but shudder at the thought of the accident.', '그녀는 그 사고를 생각하자 몸을 떨지 않을 수 없었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('shuffle', '발을 끌다', '[{"pos": "v.", "ko": "발을 끌며 걷다"}, {"pos": "v.", "ko": "(카드 등을) 섞다"}, {"pos": "n.", "ko": "발을 끄는 걸음"}]'::jsonb, 'He tends to shuffle his feet when he is nervous.', '그는 긴장할 때 발을 끄는 버릇이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('sibling', '형제자매', '[{"pos": "n.", "ko": "형제자매, 남매"}]'::jsonb, 'She has two siblings, one older brother and one younger sister.', '그녀에게는 오빠 한 명과 여동생 한 명, 이렇게 두 명의 형제자매가 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('sight', '시력', '[{"pos": "n.", "ko": "시력, 시야"}, {"pos": "n.", "ko": "광경, 풍경"}, {"pos": "n.", "ko": "보기, 목격"}]'::jsonb, 'After the surgery, he regained his sight and could see clearly again.', '수술 후 그는 시력을 되찾아 다시 뚜렷이 볼 수 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('signify', '의미하다', '[{"pos": "v.", "ko": "의미하다, 나타내다"}, {"pos": "v.", "ko": "중요하다, 영향을 끼치다"}]'::jsonb, 'A red rose can signify love or respect in many cultures.', '붉은 장미는 많은 문화에서 사랑이나 존경을 의미할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('simplicity', '단순함', '[{"pos": "n.", "ko": "단순함, 간단함"}, {"pos": "n.", "ko": "소박함, 꾸밈없음"}]'::jsonb, 'The simplicity of the design makes the product easy to use.', '디자인의 단순함 덕분에 그 제품은 사용하기 쉽다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('simulate', '흉내 내다', '[{"pos": "v.", "ko": "흉내 내다, 모방하다"}, {"pos": "v.", "ko": "가장하다, ~인 척하다"}, {"pos": "v.", "ko": "모의실험하다"}]'::jsonb, 'Pilots often simulate emergencies to prepare for real situations.', '조종사들은 실제 상황에 대비해 비상사태를 흉내 내곤 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('simultaneously', '동시에', '[{"pos": "ad.", "ko": "동시에, 한꺼번에"}]'::jsonb, 'All the lights in the building went out simultaneously during the storm.', '폭풍이 치는 동안 건물의 모든 불이 동시에 꺼졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('sink', '가라앉다', '[{"pos": "v.", "ko": "가라앉다, 침몰하다"}, {"pos": "v.", "ko": "(수준·기분 등이) 떨어지다, 나빠지다"}, {"pos": "n.", "ko": "싱크대, 세면대"}]'::jsonb, 'The small boat began to sink after hitting a rock.', '작은 배는 바위에 부딪힌 뒤 가라앉기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('skeleton', '뼈대', '[{"pos": "n.", "ko": "뼈대, 해골"}, {"pos": "n.", "ko": "골격, 기본 구조"}]'::jsonb, 'The skeleton of the dinosaur was displayed in the museum.', '공룡의 뼈대가 박물관에 전시되어 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('skinny', '마른', '[{"pos": "a.", "ko": "마른, 깡마른"}, {"pos": "a.", "ko": "몸에 딱 붙는"}]'::jsonb, 'He was so skinny that his clothes looked too big for him.', '그는 너무 마른 탓에 옷이 헐렁해 보였다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('skip', '건너뛰다', '[{"pos": "v.", "ko": "건너뛰다, 생략하다"}, {"pos": "v.", "ko": "깡충깡충 뛰다"}]'::jsonb, 'You can skip the first chapter if you already know the basics.', '기초를 이미 안다면 첫 장은 건너뛰어도 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('skull', '두개골', '[{"pos": "n.", "ko": "두개골, 해골"}]'::jsonb, 'The archaeologists discovered an ancient skull in the cave.', '고고학자들은 동굴에서 오래된 두개골을 발견했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('skyscraper', '고층 건물', '[{"pos": "n.", "ko": "고층 건물, 마천루"}]'::jsonb, 'The new skyscraper became the tallest building in the city.', '새 고층 건물이 그 도시에서 가장 높은 건물이 되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('slaughter', '도살하다', '[{"pos": "v.", "ko": "도살하다, 학살하다"}, {"pos": "n.", "ko": "도살, 학살"}]'::jsonb, 'Farmers slaughter animals for food in a humane way.', '농부들은 동물을 인도적으로 도살해 식품으로 쓴다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('slave', '노예', '[{"pos": "n.", "ko": "노예"}, {"pos": "v.", "ko": "혹사하다, 고되게 일하다"}]'::jsonb, 'In the past, a slave had no freedom or rights.', '과거에는 노예에게 자유나 권리가 없었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('slice', '얇게 썬 조각', '[{"pos": "n.", "ko": "얇게 썬 조각"}, {"pos": "v.", "ko": "얇게 자르다"}, {"pos": "n.", "ko": "일부분, 단면"}]'::jsonb, 'He ate a slice of bread with his breakfast every morning.', '그는 매일 아침 식사로 빵 한 조각을 먹었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
