INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('slip', '미끄러지다', '[{"pos": "v.", "ko": "미끄러지다"}, {"pos": "n.", "ko": "실수, 과실"}, {"pos": "v.", "ko": "살짝 움직이다, 슬며시 가다"}]'::jsonb, 'Be careful not to slip on the wet floor in the hallway.', '복도에 젖은 바닥에서 미끄러지지 않도록 조심해라.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('slogan', '구호', '[{"pos": "n.", "ko": "구호, 슬로건"}, {"pos": "n.", "ko": "광고 문구"}, {"pos": "n.", "ko": "표어"}]'::jsonb, 'The company created a new slogan to attract more customers.', '그 회사는 더 많은 고객을 끌기 위해 새로운 구호를 만들었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('snatch', '와락 잡다', '[{"pos": "v.", "ko": "와락 잡다, 낚아채다"}, {"pos": "n.", "ko": "잡아챔, 순간"}, {"pos": "v.", "ko": "빼앗다"}]'::jsonb, 'The boy tried to snatch the ball from his friend during the game.', '그 소년은 경기 중에 친구에게서 공을 와락 잡으려 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
