INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strike', '치다', '[{"pos": "v.", "ko": "치다, 때리다"}, {"pos": "n.", "ko": "파업"}, {"pos": "v.", "ko": "(생각이) 떠오르다, 인상을 주다"}]'::jsonb, 'Lightning can strike trees during a thunderstorm.', '번개는 천둥번개가 칠 때 나무를 칠 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('string', '끈', '[{"pos": "n.", "ko": "끈, 실"}, {"pos": "n.", "ko": "연속, 일련"}, {"pos": "v.", "ko": "실로 꿰다"}]'::jsonb, 'He tied the package with a piece of string before mailing it.', '그는 소포를 우체국에 보내기 전에 끈으로 묶었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
