INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strive', '노력하다', '[{"pos": "v.", "ko": "노력하다, 애쓰다"}, {"pos": "v.", "ko": "분투하다"}]'::jsonb, 'Many students strive to achieve high scores on their exams.', '많은 학생들이 시험에서 높은 점수를 받으려고 노력한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stroke', '뇌졸중', '[{"pos": "n.", "ko": "뇌졸중"}, {"pos": "n.", "ko": "타격, 한 번 치기"}, {"pos": "n.", "ko": "쓰다듬기, 어루만지기"}]'::jsonb, 'Quick medical attention is crucial when someone has a stroke.', '누군가 뇌졸중이 오면 신속한 치료가 매우 중요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('structural', '구조상의', '[{"pos": "a.", "ko": "구조상의, 조직상의"}]'::jsonb, 'Engineers checked for any structural damage after the earthquake.', '엔지니어들이 지진 후 구조상의 손상이 있는지 점검했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('struggle', '고군분투하다', '[{"pos": "v.", "ko": "고군분투하다, 힘겹게 싸우다"}, {"pos": "n.", "ko": "분투, 노력"}]'::jsonb, 'She had to struggle to balance her studies and part-time job.', '그녀는 학업과 아르바이트를 병행하려고 고군분투했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stubborn', '고집 센', '[{"pos": "a.", "ko": "고집 센, 완고한"}, {"pos": "a.", "ko": "쉽게 바뀌지 않는, 완강한"}]'::jsonb, 'He is so stubborn that he never changes his mind easily.', '그는 고집이 세서 좀처럼 생각을 바꾸지 않는다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stuff', '물건', '[{"pos": "n.", "ko": "물건, 물질"}, {"pos": "v.", "ko": "채워 넣다, 속을 채우다"}]'::jsonb, 'She put all her stuff into a large suitcase before leaving for college.', '그녀는 대학에 가기 전에 자신의 모든 물건을 큰 여행가방에 넣었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stun', '깜짝 놀라게 하다', '[{"pos": "v.", "ko": "깜짝 놀라게 하다"}, {"pos": "v.", "ko": "기절시키다, 정신을 잃게 하다"}]'::jsonb, 'The news of his sudden resignation stunned everyone in the office.', '그의 갑작스러운 사직 소식에 사무실 모두가 깜짝 놀랐다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('sturdy', '튼튼한', '[{"pos": "a.", "ko": "튼튼한, 견고한"}, {"pos": "a.", "ko": "건강한, 억센"}]'::jsonb, 'This sturdy table can easily support the weight of several heavy books.', '이 튼튼한 탁자는 무거운 책 여러 권도 거뜬히 올릴 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('subdue', '진압하다', '[{"pos": "v.", "ko": "진압하다, 제압하다"}, {"pos": "v.", "ko": "억누르다, 완화하다"}]'::jsonb, 'The firefighters worked hard to subdue the flames before they spread further.', '소방관들은 불길이 더 번지기 전에 진압하려고 애썼다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('subjective', '주관적인', '[{"pos": "a.", "ko": "주관적인, 개인적인"}]'::jsonb, 'Your opinion about the movie is subjective and may differ from others.', '그 영화에 대한 너의 평가는 주관적이어서 다른 사람들과 다를 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('submit', '제출하다', '[{"pos": "v.", "ko": "제출하다"}, {"pos": "v.", "ko": "복종하다, 굴복하다"}]'::jsonb, 'Please submit your application form before the end of this week.', '이번 주가 끝나기 전에 신청서를 제출하세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
