INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('suicide', '자살', '[{"pos": "n.", "ko": "자살"}, {"pos": "n.", "ko": "자살 행위"}]'::jsonb, 'The novel deals with the sensitive topic of suicide among teenagers.', '그 소설은 청소년들 사이의 자살이라는 민감한 주제를 다룬다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('suitable', '적합한', '[{"pos": "a.", "ko": "적합한, 알맞은"}, {"pos": "a.", "ko": "적절한"}]'::jsonb, 'These shoes are suitable for hiking in the mountains.', '이 신발은 산에서 등산하기에 적합하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
