INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tame', '길들여진', '[{"pos": "a.", "ko": "길들여진, 온순한"}, {"pos": "v.", "ko": "길들이다, 다루기 쉽게 하다"}, {"pos": "a.", "ko": "재미없는, 단조로운"}]'::jsonb, 'The once wild horse is now tame and friendly to people.', '한때 야생이던 말이 이제는 길들여져 사람들에게 친근하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
