INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tangle', '엉키다', '[{"pos": "v.", "ko": "엉키다, 얽히다"}, {"pos": "n.", "ko": "엉킴, 혼란"}, {"pos": "v.", "ko": "혼란스럽게 하다"}]'::jsonb, 'The wires began to tangle when I tried to move the computer.', '컴퓨터를 옮기려다 보니 선들이 엉키기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('target', '목표', '[{"pos": "n.", "ko": "목표, 표적"}, {"pos": "n.", "ko": "대상, 목표물"}, {"pos": "v.", "ko": "목표로 삼다, 겨냥하다"}]'::jsonb, 'The company set a high sales target for this year.', '회사는 올해 높은 판매 목표를 세웠다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tariff', '관세', '[{"pos": "n.", "ko": "관세, 세율"}, {"pos": "n.", "ko": "요금표, 가격표"}]'::jsonb, 'The government decided to lower the tariff on imported goods.', '정부는 수입품에 대한 관세를 인하하기로 결정했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tease', '놀리다', '[{"pos": "v.", "ko": "(장난스럽게) 놀리다, 괴롭히다"}, {"pos": "n.", "ko": "장난치는 사람, 놀리는 사람"}]'::jsonb, 'He used to tease his younger sister about her glasses.', '그는 여동생의 안경을 두고 자주 놀리곤 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
