INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temperament', '기질', '[{"pos": "n.", "ko": "기질, 성격"}, {"pos": "n.", "ko": "성향, 성질"}]'::jsonb, 'His artistic temperament makes him sensitive to beauty.', '그의 예술가적 기질은 아름다움에 민감하게 만든다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
