INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tempt', '유혹하다', '[{"pos": "v.", "ko": "유혹하다, 끌어들이다"}, {"pos": "v.", "ko": "~할 마음이 들게 하다"}]'::jsonb, 'The smell of freshly baked bread tempted her to enter the bakery.', '갓 구운 빵 냄새가 그녀를 빵집으로 유혹했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tenant', '세입자', '[{"pos": "n.", "ko": "세입자, 임차인"}]'::jsonb, 'The tenant agreed to pay the rent on the first day of each month.', '세입자는 매달 첫째 날에 집세를 내기로 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tend', '경향이 있다', '[{"pos": "v.", "ko": "~하는 경향이 있다"}, {"pos": "v.", "ko": "돌보다, 보살피다"}]'::jsonb, 'Teenagers tend to stay up late on weekends and sleep in the next morning.', '십대들은 주말에 늦게까지 깨어 있고 다음 날 늦잠을 자는 경향이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
