INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('tension', '긴장', '[{"pos": "n.", "ko": "긴장 (상태)"}, {"pos": "n.", "ko": "팽팽함"}]'::jsonb, 'There was a lot of tension between the two teams during the final match.', '결승전에서 두 팀 사이에는 긴장이 감돌았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
