INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('terrain', '지형', '[{"pos": "n.", "ko": "지형, 지세"}]'::jsonb, 'The rough terrain made it difficult for the hikers to reach the summit.', '험한 지형 때문에 등산객들이 정상에 오르기 어려웠다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
