INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('theft', '절도', '[{"pos": "n.", "ko": "절도, 도둑질"}]'::jsonb, 'The store installed cameras to prevent theft.', '가게는 절도를 막기 위해 카메라를 설치했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
