INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('threat', '위협', '[{"pos": "n.", "ko": "위협, 협박"}, {"pos": "n.", "ko": "위험 요소"}]'::jsonb, 'The threat of a storm forced the event to be canceled.', '폭풍의 위협 때문에 행사가 취소되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
