INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('vote', '투표하다', '[{"pos": "v.", "ko": "투표하다"}, {"pos": "n.", "ko": "투표"}, {"pos": "n.", "ko": "표"}]'::jsonb, 'Citizens over eighteen can vote in the national elections.', '18세 이상 시민은 전국 선거에서 투표할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('vow', '맹세', '[{"pos": "n.", "ko": "맹세"}, {"pos": "v.", "ko": "맹세하다"}]'::jsonb, 'She made a vow to study harder for the next exam.', '그녀는 다음 시험을 위해 더 열심히 공부하겠다고 맹세했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
