INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('wrench', '비틀다', '[{"pos": "v.", "ko": "비틀다, 억지로 빼앗다"}, {"pos": "n.", "ko": "렌치, 스패너"}]'::jsonb, 'He tried to wrench the door open when it got stuck.', '문이 끼었을 때 그는 억지로 비틀어 열려고 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('wrestle', '레슬링하다', '[{"pos": "v.", "ko": "레슬링을 하다, 몸싸움하다"}, {"pos": "v.", "ko": "씨름하다"}]'::jsonb, 'The two athletes wrestle for the championship title every year.', '두 선수는 매년 챔피언 자리를 놓고 레슬링을 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('yearn', '갈망하다', '[{"pos": "v.", "ko": "갈망하다, 그리워하다"}]'::jsonb, 'Many students yearn for a long vacation after exams.', '많은 학생들이 시험이 끝난 뒤 긴 방학을 갈망한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('yeast', '효모', '[{"pos": "n.", "ko": "효모"}]'::jsonb, 'Yeast is used to make bread rise during baking.', '효모는 빵을 구울 때 부풀게 하는 데 사용된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('yield', '산출하다', '[{"pos": "v.", "ko": "산출하다, 생산하다"}, {"pos": "v.", "ko": "양보하다, 굴복하다"}]'::jsonb, 'The farm yields enough vegetables to supply the whole village.', '그 농장은 마을 전체에 공급할 만큼의 채소를 생산한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
